"""Persistent chat sessions for the Carter agent.

Each session is a JSON file under `~/.gemma4/sessions/<session_id>.json` with
shape:

    {
      "id": "<uuid hex>",
      "created_at": "<isoformat>",
      "updated_at": "<isoformat>",
      "title": "<auto-generated or user-set>",
      "turns": [
        {"role": "user", "content": "...", "ts": "..."},
        {"role": "assistant", "content": "...", "ts": "...", "tool_count": 2},
        ...
      ]
    }

The CLI uses this to give continuity between `python -m gemma4_agent.support.chat`
invocations. The agent's `history` (which holds `tool` role messages with raw
JSON tool results) is NOT what we save here; we save a compact user-visible
transcript that survives across sessions.

Disable with env `GEMMA4_AGENT_SESSIONS=false` (default ON).
"""
from __future__ import annotations

import json
import os
import threading
import uuid
from dataclasses import asdict, dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Any


def is_enabled() -> bool:
    raw = (os.environ.get("GEMMA4_AGENT_SESSIONS") or "").strip().casefold()
    if raw in {"0", "false", "no", "off"}:
        return False
    return True


def sessions_dir() -> Path:
    """Where session JSONs live. Honors GEMMA4_AGENT_SESSIONS_DIR override."""
    override = os.environ.get("GEMMA4_AGENT_SESSIONS_DIR")
    if override:
        return Path(override).expanduser().resolve()
    return Path.home() / ".gemma4" / "sessions"


def _now_iso() -> str:
    return datetime.now().isoformat(timespec="seconds")


@dataclass
class SessionTurn:
    role: str
    content: str
    ts: str = field(default_factory=_now_iso)
    tool_count: int = 0


@dataclass
class Session:
    id: str
    created_at: str
    updated_at: str
    title: str
    turns: list[SessionTurn] = field(default_factory=list)

    @classmethod
    def new(cls, *, title: str = "") -> "Session":
        ts = _now_iso()
        return cls(
            id=uuid.uuid4().hex[:12],
            created_at=ts,
            updated_at=ts,
            title=title or "(sin titulo)",
            turns=[],
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "created_at": self.created_at,
            "updated_at": self.updated_at,
            "title": self.title,
            "turns": [asdict(t) for t in self.turns],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "Session":
        raw_turns = data.get("turns") or []
        turns: list[SessionTurn] = []
        for t in raw_turns:
            if not isinstance(t, dict):
                continue
            try:
                tc = int(t.get("tool_count") or 0)
            except (TypeError, ValueError):
                tc = 0
            turns.append(SessionTurn(
                role=str(t.get("role") or ""),
                content=str(t.get("content") or ""),
                ts=str(t.get("ts") or ""),
                tool_count=tc,
            ))
        return cls(
            id=str(data.get("id") or uuid.uuid4().hex[:12]),
            created_at=str(data.get("created_at") or _now_iso()),
            updated_at=str(data.get("updated_at") or _now_iso()),
            title=str(data.get("title") or "(sin titulo)"),
            turns=turns,
        )


class SessionStore:
    def __init__(self, root: Path | None = None) -> None:
        self.root = root or sessions_dir()
        self.root.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()

    def _path(self, session_id: str) -> Path:
        safe = "".join(c for c in session_id if c.isalnum())[:32]
        if not safe:
            raise ValueError(f"invalid session id: {session_id!r}")
        return self.root / f"{safe}.json"

    def save(self, session: Session) -> dict[str, Any]:
        from .state import atomic_write_json
        with self._lock:
            session.updated_at = _now_iso()
            path = self._path(session.id)
            try:
                atomic_write_json(path, session.to_dict())
            except OSError as exc:
                return {"ok": False, "error": str(exc), "path": str(path)}
            return {"ok": True, "id": session.id, "path": str(path), "turns": len(session.turns)}

    def load(self, session_id: str) -> Session | None:
        with self._lock:
            path = self._path(session_id)
            if not path.is_file():
                return None
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                return None
        if not isinstance(data, dict):
            return None
        return Session.from_dict(data)

    def delete(self, session_id: str) -> dict[str, Any]:
        with self._lock:
            path = self._path(session_id)
            existed = path.is_file()
            try:
                if existed:
                    path.unlink()
            except OSError as exc:
                return {"ok": False, "error": str(exc), "id": session_id}
            return {"ok": True, "id": session_id, "existed": existed}

    def list_sessions(self, limit: int = 50) -> list[dict[str, Any]]:
        """Return sessions sorted by updated_at descending (most recent first)."""
        out: list[dict[str, Any]] = []
        with self._lock:
            for path in self.root.glob("*.json"):
                try:
                    data = json.loads(path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    continue
                if not isinstance(data, dict):
                    continue
                turns = data.get("turns") or []
                out.append({
                    "id": str(data.get("id") or path.stem),
                    "title": str(data.get("title") or "(sin titulo)"),
                    "created_at": str(data.get("created_at") or ""),
                    "updated_at": str(data.get("updated_at") or ""),
                    "turn_count": len(turns) if isinstance(turns, list) else 0,
                    "path": str(path),
                })
        out.sort(key=lambda d: d.get("updated_at") or "", reverse=True)
        return out[:limit]


def auto_title(first_user_msg: str, *, chat_fn: Any | None = None, max_words: int = 6) -> str:
    """Generate a short title for a session.

    If `chat_fn` is provided, call the LLM with a tight prompt (1 call, capped
    at ~30 tokens) asking for a short title. Otherwise, fall back to a
    heuristic: take the first N words of the user message, strip noise.
    """
    text = (first_user_msg or "").strip()
    if not text:
        return "(sin titulo)"
    if chat_fn is None:
        return _heuristic_title(text, max_words=max_words)
    prompt = (
        "Genera un titulo MUY corto (max 6 palabras, sin comillas, sin emojis, "
        "sin punto final) que resuma este mensaje del usuario. Solo el titulo, "
        "nada mas:\n\n"
        f"{text[:300]}"
    )
    try:
        result = chat_fn([
            {"role": "system", "content": "Eres un asistente que crea titulos breves."},
            {"role": "user", "content": prompt},
        ])
    except Exception:
        return _heuristic_title(text, max_words=max_words)
    if not isinstance(result, dict):
        return _heuristic_title(text, max_words=max_words)
    try:
        choice = (result.get("choices") or [{}])[0]
        msg = choice.get("message") or {}
        content = str(msg.get("content") or "").strip()
    except (KeyError, IndexError, TypeError):
        return _heuristic_title(text, max_words=max_words)
    if not content:
        return _heuristic_title(text, max_words=max_words)
    return _clean_title(content, max_words=max_words)


def _heuristic_title(text: str, *, max_words: int) -> str:
    cleaned = " ".join(text.split())[:120]
    parts = cleaned.split()
    return " ".join(parts[:max_words]) or "(sin titulo)"


def _clean_title(raw: str, *, max_words: int) -> str:
    title = raw.strip().strip("\"'`.,;:!?")
    title = title.replace("\n", " ")
    parts = title.split()
    return " ".join(parts[:max_words]) or "(sin titulo)"
